// Generated by plugins/accessibility-order. Edit the copy there, not the one in ios/.
#import "AccessibilityOrderFlag.h"

#import <objc/message.h>
#import <objc/runtime.h>

#import <React/RCTViewComponentView.h>
#import <react/featureflags/ReactNativeFeatureFlags.h>
#import <react/featureflags/ReactNativeFeatureFlagsOverridesOSSStable.h>
#import <react/renderer/components/view/ViewProps.h>

using namespace facebook::react;

namespace {

// React Native's stable flags, plus reading order.
class StableFlagsWithAccessibilityOrder : public ReactNativeFeatureFlagsOverridesOSSStable {
 public:
  bool enableAccessibilityOrder() override
  {
    return true;
  }
};

// --- Reading-order fix ---------------------------------------------------------------------------
//
// React Native (checked in 0.88.1) builds a view's VoiceOver order list in two places:
//  - in -updateProps:, when `experimental_accessibilityOrder` changes. That runs before the view
//    stores the new props, so the list is built from the previous order. The first order a view
//    gets (ScreenReaderOrderScope sends it on its second render) is built from an empty order, so
//    VoiceOver falls back to physical order. Each later change applies the order before it.
//  - in -didMoveToSuperview. Children added after that are never picked up.
// The fix gives RCTViewComponentView an `accessibilityElements` getter that builds the list from
// the current props and subviews each time VoiceOver asks for it.

// UIView's own getter, resolved at call time (VoiceOver's accessibility bundle can replace it
// after launch).
NSArray *superAccessibilityElements(RCTViewComponentView *self, SEL _cmd)
{
  struct objc_super parent = {self, [UIView class]};
  return ((NSArray * (*)(struct objc_super *, SEL)) objc_msgSendSuper)(&parent, _cmd);
}

void collectViews(UIView *view, NSSet<NSString *> *nativeIDs, NSMutableDictionary<NSString *, UIView *> *found)
{
  for (UIView *subview in view.subviews) {
    if ([subview isKindOfClass:[RCTViewComponentView class]]) {
      NSString *nativeID = ((RCTViewComponentView *)subview).nativeId;
      if (nativeID != nil && [nativeIDs containsObject:nativeID]) {
        found[nativeID] = subview;
      }
    }
    collectViews(subview, nativeIDs, found);
  }
}

NSArray *orderedAccessibilityElements(RCTViewComponentView *self, SEL _cmd)
{
  auto props = std::static_pointer_cast<const ViewProps>([self props]);
  if (!ReactNativeFeatureFlags::enableAccessibilityOrder() || !props || props->accessibilityOrder.empty()) {
    return superAccessibilityElements(self, _cmd);
  }

  NSMutableArray<NSString *> *order = [NSMutableArray arrayWithCapacity:props->accessibilityOrder.size()];
  for (const auto &nativeID : props->accessibilityOrder) {
    [order addObject:[NSString stringWithUTF8String:nativeID.c_str()]];
  }
  NSMutableDictionary<NSString *, UIView *> *found = [NSMutableDictionary new];
  collectViews(self, [NSSet setWithArray:order], found);

  NSMutableArray *elements = [NSMutableArray arrayWithCapacity:order.count];
  for (NSString *nativeID in order) {
    UIView *view = found[nativeID];
    if (view != nil) {
      [elements addObject:view];
    }
  }
#if DEBUG
  // Logs each new result once per view, to check what VoiceOver gets.
  NSMutableArray<NSString *> *spoken = [NSMutableArray new];
  for (UIView *element in elements) {
    [spoken addObject:element.accessibilityLabel ?: @"(no label)"];
  }
  NSString *summary = [NSString stringWithFormat:@"%lu of %lu IDs found: %@",
                                                 (unsigned long)elements.count,
                                                 (unsigned long)order.count,
                                                 [spoken componentsJoinedByString:@" | "]];
  static const void *lastSummaryKey = &lastSummaryKey;
  if (![objc_getAssociatedObject(self, lastSummaryKey) isEqualToString:summary]) {
    objc_setAssociatedObject(self, lastSummaryKey, summary, OBJC_ASSOCIATION_COPY_NONATOMIC);
    NSLog(@"[AccessibilityOrderFlag] accessibilityElements on %p: %@", self, summary);
  }
#endif
  return elements;
}

void installReadingOrderFix()
{
  SEL selector = @selector(accessibilityElements);
  Method uiViewMethod = class_getInstanceMethod([UIView class], selector);
  // Adds the getter only if React Native doesn't define one itself (a newer version might).
  BOOL added = class_addMethod(
      [RCTViewComponentView class], selector, (IMP)orderedAccessibilityElements, method_getTypeEncoding(uiViewMethod));
#if DEBUG
  NSLog(@"[AccessibilityOrderFlag] reading-order fix %@", added ? @"installed" : @"NOT installed (RCTViewComponentView already has accessibilityElements)");
#else
  (void)added;
#endif
}

} // namespace

@implementation AccessibilityOrderFlag

+ (void)enable
{
  installReadingOrderFix();

  // ExpoReactNativeFactory picks the release level from this Info.plist key (default "stable").
  // The canary and experimental levels already turn the flag on.
  NSString *releaseLevel = [[NSBundle mainBundle] objectForInfoDictionaryKey:@"ReactNativeReleaseLevel"];
  if ([releaseLevel isEqualToString:@"canary"] || [releaseLevel isEqualToString:@"experimental"]) {
    return;
  }

  // The factory has just applied the stable flags, and a normal override is only allowed once,
  // so replace them. React Native hasn't started, so nothing has read a flag yet.
  auto readTooEarly = ReactNativeFeatureFlags::dangerouslyForceOverride(
      std::make_unique<StableFlagsWithAccessibilityOrder>());
#if DEBUG
  if (readTooEarly.has_value()) {
    NSLog(@"[AccessibilityOrderFlag] Flags read before the override keep their old values: %s",
          readTooEarly->c_str());
  }
  NSLog(@"[AccessibilityOrderFlag] enableAccessibilityOrder = %d", ReactNativeFeatureFlags::enableAccessibilityOrder());
#endif
}

@end
